from __future__ import annotations


COMMAND_CENTER_LAYOUT_VERSION = "v6_full_command_center"


DASHBOARD_COMMAND_CENTER_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#06111a">
<meta name="color-scheme" content="dark">
<title>Portfolio Command Center</title>
<style>
:root{--bg:#06111a;--panel:#0b1a25;--panel2:#08151e;--line:#213b4c;--text:#edf7fb;--muted:#91aabb;--good:#39d47d;--warn:#f4cf4f;--bad:#ff7884;--blue:#65c7ff;--purple:#b8a1ff}
*{box-sizing:border-box}body{margin:0;background:linear-gradient(#051019,#081722);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:1220px;margin:auto;padding:18px}.section,.hero-card{background:var(--panel);border:1px solid var(--line);border-radius:20px;padding:18px;margin-bottom:16px}.top{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;margin-bottom:16px}.eyebrow,.k{text-transform:uppercase;color:var(--muted);font-size:10px;font-weight:850;letter-spacing:.08em}.title{font-size:30px;font-weight:900;letter-spacing:-.03em}.sub,.meta,.d,.time{color:var(--muted);line-height:1.45}.top-actions{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}.badge,.btn{border:1px solid var(--line);border-radius:999px;padding:7px 11px;font-size:11px;font-weight:850;letter-spacing:.05em;background:transparent;color:var(--text);white-space:nowrap}.btn{cursor:pointer}.badge.good{border-color:#1f7041;color:#a9f5c8}.badge.warn{border-color:#76651c;color:#ffe780}.badge.bad{border-color:#7a3240;color:#ffc0c6}.badge.paper{border-color:#594c82;color:#d9d0ff}.hero{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(290px,.85fr);gap:14px}.nav{font-size:clamp(42px,8vw,72px);font-weight:900;line-height:1;letter-spacing:-.055em;margin:12px 0 8px}.return{font-size:19px;font-weight:850}.status-list{display:grid;gap:11px}.status-row{display:flex;justify-content:space-between;gap:14px;padding-bottom:10px;border-bottom:1px solid var(--line)}.status-row:last-child{border:0;padding:0}.status-val{font-weight:850;text-align:right}.goodtext{color:var(--good)}.warntext{color:var(--warn)}.badtext{color:var(--bad)}.metrics,.summary,.runtime-grid{display:grid;gap:9px}.metrics{grid-template-columns:repeat(8,minmax(110px,1fr));margin-bottom:16px}.summary{grid-template-columns:repeat(6,minmax(120px,1fr))}.runtime-grid{grid-template-columns:repeat(3,minmax(180px,1fr))}.metric,.stat,.runtime-card{background:var(--panel2);border:1px solid var(--line);border-radius:13px;padding:11px}.v{font-size:20px;font-weight:900;margin-top:4px}.metric.good,.stat.good{border-color:#1e6139;background:#092418}.metric.warn,.stat.warn{border-color:#6d5d19;background:#211e0b}.metric.bad,.stat.bad{border-color:#71323b;background:#241016}.section-head{display:flex;justify-content:space-between;gap:12px;align-items:baseline;margin-bottom:14px}.name,.section-title{font-size:20px;font-weight:900}.section-note{color:var(--muted);font-size:12px}.grid2{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(300px,.85fr);gap:14px}.chart-wrap{height:255px;position:relative}.chart{width:100%;height:100%;display:block}.chart-empty{position:absolute;inset:0;display:grid;place-items:center;color:var(--muted)}.attribution{display:grid;gap:9px}.bar-row{display:grid;grid-template-columns:minmax(110px,1fr) 2fr auto;gap:9px;align-items:center}.bar-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.bar-track{height:9px;border-radius:999px;background:#071019;overflow:hidden}.bar-fill{height:100%;background:var(--blue)}.bar-fill.neg{background:var(--bad)}.bar-val{font-weight:800}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px}table{width:100%;border-collapse:collapse;min-width:760px}th,td{text-align:left;padding:10px 11px;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:9px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);background:#07131c}.num{text-align:right}.mobile-list{display:none}.item,.queue-item,.history-item{padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--panel2);margin-bottom:8px}.item-top,.queue-title{display:flex;justify-content:space-between;gap:10px}.item-title{font-weight:850}.item-sub{font-size:11px;color:var(--muted);margin-top:4px}.cards{display:grid;gap:14px}.card{background:var(--panel2);border:1px solid var(--line);border-radius:18px;padding:16px}.cardhead{display:flex;justify-content:space-between;gap:12px}.cardmetrics{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:8px;margin-top:13px}.strip{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:9px}.strip .v{font-size:15px}.reason{margin-top:12px;color:#c7dce7;line-height:1.5}.next{margin-top:6px;color:#e4f8ff;line-height:1.45}.details{margin-top:10px;border-top:1px solid var(--line);padding-top:9px}details summary{cursor:pointer;color:#bce9ff;font-weight:750}.strategy{margin-top:8px;padding:9px;border:1px solid var(--line);border-radius:10px}.error{display:none;border:1px solid #7a3240;background:#241016;color:#ffc0c6;border-radius:13px;padding:12px;margin-bottom:16px}.error.show{display:block}.footer{color:var(--muted);font-size:11px;text-align:center;padding:8px}.muted{color:var(--muted)}
@media(max-width:1050px){.metrics{grid-template-columns:repeat(4,1fr)}.hero,.grid2{grid-template-columns:1fr}.runtime-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:850px){.summary{grid-template-columns:repeat(3,1fr)}.cardmetrics,.strip{grid-template-columns:repeat(2,1fr)}}
@media(max-width:650px){.wrap{padding:10px}.top{display:block}.top-actions{justify-content:flex-start;margin-top:12px}.metrics,.summary,.runtime-grid{grid-template-columns:repeat(2,1fr)}.section,.hero-card{padding:14px;border-radius:16px}.title{font-size:25px}.name,.section-title{font-size:18px}.table-wrap{display:none}.mobile-list{display:block}.chart-wrap{height:210px}}
</style>
</head>
<body><main class="wrap">
<header class="top"><div><div class="eyebrow">Crypto Opportunity Engine</div><div class="title">Portfolio Command Center</div><div class="sub">Canonical paper portfolio + current mechanism truth. Portfolio, runtime, evidence, and research conclusions are read from the same persisted production snapshot.</div></div><div class="top-actions"><span class="badge paper">PAPER · $250K GENESIS</span><span class="badge good">AUTO PAPER EXECUTION · ON</span><span class="badge bad">LIVE MONEY · DISABLED</span><span id="contract" class="badge">V5</span><button id="refreshBtn" class="btn">REFRESH</button></div></header>
<div id="error" class="error"></div>
<section class="hero"><div class="hero-card"><div class="k">Current portfolio NAV</div><div id="nav" class="nav">—</div><div id="totalReturn" class="return muted">— since $250,000 genesis</div><div id="updated" class="meta" style="margin-top:10px">Awaiting portfolio snapshot…</div><div id="valuationDetail" class="meta" style="margin-top:4px"></div></div><div class="hero-card"><div class="status-list"><div class="status-row"><span class="muted">Portfolio</span><span class="status-val">Canonical / persistent</span></div><div class="status-row"><span class="muted">Paper execution</span><span class="status-val goodtext">Automatic</span></div><div class="status-row"><span class="muted">Live execution</span><span class="status-val badtext">No authority</span></div><div class="status-row"><span class="muted">Runtime</span><span id="runtimeStatus" class="status-val">—</span></div><div class="status-row"><span class="muted">Valuation</span><span id="valuationStatus" class="status-val">—</span></div><div class="status-row"><span class="muted">Opportunity families</span><span id="familyStatus" class="status-val">—</span></div><div class="status-row"><span class="muted">Mechanisms certified</span><span id="certifiedCount" class="status-val">—</span></div></div></div></section>
<section class="metrics"><div class="metric"><div class="k">Starting capital</div><div class="v">$250,000</div></div><div class="metric"><div class="k">Cash</div><div id="cash" class="v">—</div></div><div class="metric"><div class="k">Deployed</div><div id="deployed" class="v">—</div></div><div class="metric"><div class="k">Realized P&L</div><div id="realized" class="v">—</div></div><div class="metric"><div class="k">Unrealized P&L</div><div id="unrealized" class="v">—</div></div><div class="metric"><div class="k">Max drawdown</div><div id="maxdd" class="v">—</div></div><div class="metric"><div class="k">Open positions</div><div id="openCount" class="v">—</div></div><div class="metric"><div class="k">Closed trades</div><div id="tradeCount" class="v">—</div></div></section>
<section class="section"><div class="section-head"><div><div class="section-title">Runtime health</div><div class="section-note">Durable worker heartbeats · diagnostic only</div></div><div id="systemLine" class="section-note">Loading…</div></div><div id="runtimeGrid" class="runtime-grid"></div></section>
<section class="grid2"><div class="section"><div class="section-head"><div class="section-title">Equity curve</div><div id="historyCount" class="section-note">0 NAV snapshots</div></div><div class="chart-wrap"><canvas id="equityChart" class="chart"></canvas><div id="chartEmpty" class="chart-empty">Waiting for more NAV snapshots</div></div></div><div class="section"><div class="section-head"><div class="section-title">P&L attribution</div><div class="section-note">Current + realized</div></div><div id="attribution" class="attribution"><div class="muted">No attribution yet.</div></div></div></section>
<section class="section"><div class="section-head"><div class="section-title">Open paper positions</div><div class="section-note">Marked automatically until modeled horizon</div></div><div class="table-wrap"><table><thead><tr><th>Asset / strategy</th><th>Venue</th><th>Opened</th><th>Due</th><th class="num">Capital</th><th class="num">Entry</th><th class="num">Mark</th><th class="num">Unrealized P&L</th></tr></thead><tbody id="positionsBody"></tbody></table></div><div id="positionsMobile" class="mobile-list"></div></section>
<section class="grid2"><div class="section"><div class="section-head"><div class="section-title">Recent completed trades</div><div class="section-note">Realized paper outcomes</div></div><div id="tradesList"></div></div><div class="section"><div class="section-head"><div class="section-title">Skipped / rejected allocations</div><div class="section-note">Fail-closed reasons</div></div><div id="skipsList"></div></div></section>
<section class="section"><div class="section-head"><div><div class="section-title">Cycle history backfill</div><div class="section-note">Separated historical research · never counted as forward evidence</div></div><div id="cycleHistorySummary" class="section-note">Awaiting maintenance status</div></div><div id="cycleHistoryList"></div></section>
<section class="section"><div class="section-head"><div><div class="section-title">Evidence accumulation</div><div class="section-note">Current source → candidate → forward → qualification → paper → certification</div></div><div class="section-note">Read-only progress · thresholds unchanged</div></div><div id="summary" class="summary"></div></section>
<section class="section"><div class="section-head"><div><div class="section-title">Profit mechanism certification</div><div class="section-note">V5 truthful mechanism cards · the browser does not infer investment state</div></div><div class="section-note">Provider → evidence → economics → execution → settlement → certification</div></div><div id="cards" class="cards"></div></section>
<section class="section"><div class="section-head"><div class="section-title">What needs attention next</div><div class="section-note">Current portfolio + mechanism blockers</div></div><div id="actionQueue"></div></section>
<section class="section"><div class="section-head"><div class="section-title">Active volume universe</div><div class="section-note">Research membership · no allocation authority</div></div><div id="volumeUniverse" class="meta">No universe snapshot yet.</div></section>
<div class="footer">Auto-refresh: 30 seconds · one persisted command-center snapshot per refresh · paper-only · no live execution authority</div>
</main>
<script>
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number.isFinite(+v)?Number(v).toLocaleString():'—',money=v=>Number.isFinite(+v)?new Intl.NumberFormat(undefined,{style:'currency',currency:'USD',maximumFractionDigits:2}).format(+v):'—',pct=v=>Number.isFinite(+v)?`${(+v*100).toFixed(2)}%`:'—';
function when(v){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleString()}function age(s){if(!Number.isFinite(+s))return 'age unknown';s=+s;if(s<120)return `${Math.round(s)}s old`;if(s<7200)return `${Math.round(s/60)}m old`;if(s<172800)return `${(s/3600).toFixed(1)}h old`;return `${(s/86400).toFixed(1)}d old`}function pnlClass(v){return +v>0?'goodtext':+v<0?'badtext':'muted'}
function clsStatus(s){s=String(s||'').toLowerCase();if(s.includes('certified')||s.includes('paper capable')||s==='connected'||s==='complete'||s==='current'||s==='success'||s==='running')return 'good';if(s.includes('missing')||s.includes('failure')||s.includes('poor')||s.includes('blocked')||s.includes('degraded')||s.includes('unavailable')||s.includes('error'))return 'bad';return 'warn'}
function empty(t){return `<div class="muted">${esc(t)}</div>`}function stat(k,v,d='',c=''){return `<div class="stat ${esc(c)}"><div class="k">${esc(k)}</div><div class="v">${esc(v)}</div><div class="d">${esc(d)}</div></div>`}function metric(k,v,d='',c=''){return `<div class="metric ${esc(c)}"><div class="k">${esc(k)}</div><div class="v">${esc(v)}</div><div class="d">${esc(d)}</div></div>`}
function renderChart(rows){const c=$('equityChart'),e=$('chartEmpty'),data=[...(rows||[])].reverse().filter(x=>Number.isFinite(+x.nav_usd));if(data.length<2){e.style.display='grid';const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);return}e.style.display='none';const dpr=window.devicePixelRatio||1,r=c.getBoundingClientRect();c.width=Math.max(1,r.width*dpr);c.height=Math.max(1,r.height*dpr);const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);const w=r.width,h=r.height,p=22,vals=data.map(x=>+x.nav_usd),lo=Math.min(...vals,250000),hi=Math.max(...vals,250000),span=Math.max(1,hi-lo);ctx.clearRect(0,0,w,h);ctx.strokeStyle='#213b4c';ctx.lineWidth=1;for(let i=0;i<4;i++){const y=p+(h-2*p)*i/3;ctx.beginPath();ctx.moveTo(p,y);ctx.lineTo(w-p,y);ctx.stroke()}ctx.strokeStyle='#65c7ff';ctx.lineWidth=2.5;ctx.beginPath();data.forEach((x,i)=>{const xx=p+(w-2*p)*(i/(data.length-1)),yy=h-p-(h-2*p)*((+x.nav_usd-lo)/span);i?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy)});ctx.stroke()}
function renderAttribution(a){const m=a?.pnl_by_mechanism_usd||{},s=a?.pnl_by_strategy_usd||{};let rows=[...Object.entries(m).map(([k,v])=>[`Mechanism · ${k}`,v]),...Object.entries(s).map(([k,v])=>[`Strategy · ${k}`,v])].filter(([,v])=>Number.isFinite(+v)).sort((a,b)=>Math.abs(+b[1])-Math.abs(+a[1])).slice(0,8);if(!rows.length){$('attribution').innerHTML=empty('No realized or open-position attribution yet.');return}const mx=Math.max(...rows.map(([,v])=>Math.abs(+v)),1);$('attribution').innerHTML=rows.map(([k,v])=>`<div class="bar-row"><div class="bar-name">${esc(k)}</div><div class="bar-track"><div class="bar-fill ${+v<0?'neg':''}" style="width:${Math.max(2,Math.abs(+v)/mx*100)}%"></div></div><div class="bar-val ${pnlClass(v)}">${money(v)}</div></div>`).join('')}
function renderPositions(rows){rows=rows||[];$('positionsBody').innerHTML=rows.length?rows.map(p=>`<tr><td><strong>${esc(p.asset||'—')}</strong><br><span class="muted">${esc(p.strategy||'—')}</span></td><td>${esc(p.venue||'—')}<br><span class="muted">${esc(p.symbol||'—')}</span></td><td>${when(p.opened_at)}</td><td>${when(p.due_at)}</td><td class="num">${money(p.capital_reserved_usd)}</td><td class="num">${money(p.entry_reference_price)}</td><td class="num">${money(p.current_reference_price)}</td><td class="num ${pnlClass(p.unrealized_pnl_usd)}">${money(p.unrealized_pnl_usd)}</td></tr>`).join(''):`<tr><td colspan="8" class="muted">No open paper positions.</td></tr>`;$('positionsMobile').innerHTML=rows.length?rows.map(p=>`<div class="item"><div class="item-top"><div><div class="item-title">${esc(p.asset||'—')} · ${esc(p.strategy||'—')}</div><div class="item-sub">${esc(p.venue||'—')} · due ${when(p.due_at)} · ${money(p.capital_reserved_usd)} reserved</div></div><strong class="${pnlClass(p.unrealized_pnl_usd)}">${money(p.unrealized_pnl_usd)}</strong></div></div>`).join(''):empty('No open paper positions.')}
function renderTrades(rows){$('tradesList').innerHTML=(rows||[]).length?rows.map(t=>`<div class="item"><div class="item-top"><div><div class="item-title">${esc(t.asset||'—')} · ${esc(t.strategy||'—')}</div><div class="item-sub">${esc(t.venue||'—')} · closed ${when(t.observed_at)}</div></div><strong class="${pnlClass(t.realized_pnl_delta_usd)}">${money(t.realized_pnl_delta_usd)}</strong></div></div>`).join(''):empty('No completed paper trades yet.')}
function renderSkips(rows){$('skipsList').innerHTML=(rows||[]).length?rows.map(t=>`<div class="item"><div class="item-title">${esc(t.asset||'—')} · ${esc(t.strategy||t.family||'allocation')}</div><div class="item-sub">${when(t.observed_at)} · ${esc(t.reason||'No reason recorded')}</div></div>`).join(''):empty('No skipped allocations recorded.')}
function renderCycleHistory(h){const rows=h?.assets||[];if(!h?.available){$('cycleHistorySummary').textContent='Awaiting first maintenance pass';$('cycleHistoryList').innerHTML=empty('Historical maintenance has not published durable status yet.');return}const cov=Number.isFinite(+h.overall_coverage_fraction)?pct(h.overall_coverage_fraction):'—';$('cycleHistorySummary').textContent=h.all_complete?`Complete · ${cov} coverage`:`${num(h.complete_asset_count||0)} / ${num(h.asset_count||0)} complete · ${cov} coverage`;$('cycleHistoryList').innerHTML=rows.length?rows.map(r=>`<div class="history-item"><div class="item-top"><strong>${esc(r.asset)}</strong><span class="badge ${r.complete?'good':'warn'}">${r.complete?'COMPLETE':'RETRYING'}</span></div><div class="item-sub">${num(r.quote_count||0)} / ${num(r.expected_quote_count||0)} candles · ${pct(r.coverage_fraction)} · ${r.earliest_observed_at&&r.latest_observed_at?`${when(r.earliest_observed_at)} → ${when(r.latest_observed_at)}`:'No durable range yet'}</div><div class="item-sub">${r.historical_replay_long_qualified?'Long replay support qualified':r.walk_forward_ready?'Walk-forward span ready · replay support not qualified yet':'Building walk-forward span'} · historical samples never increment genuine forward outcomes${r.next_retry_at&&!r.complete?` · next retry ${when(r.next_retry_at)}`:''}</div>${r.last_error_type?`<div class="badtext item-sub">Last fetch error: ${esc(r.last_error_type)}</div>`:''}</div>`).join(''):empty('No cycle-history assets are configured.')}
function renderRuntime(p){const cc=p.command_center||{},rt=cc.runtime||{},workers=cc.runtime_heartbeats?.workers||{},r=p.system?.research_runtime||{},po=p.system?.portfolio_runtime||{};$('systemLine').textContent=`Research ${r.status||'unknown'} · portfolio ${po.status||'unknown'} · projection ${p.system?.projection_current_for_execution?'current for paper decisions':'fail-closed'}`;const order=['research','portfolio','source_refresh','mechanism_forward','alpha_l2_sampling','heavy_worker'];$('runtimeGrid').innerHTML=order.map(k=>{const w=workers[k]||{};const state=w.available===false?(w.state||'unobserved'):(w.state||'unknown');return `<div class="runtime-card"><div class="k">${esc(k.replaceAll('_',' '))}</div><div class="v" style="font-size:16px">${esc(state)}</div><div class="d">${w.observed_at?`${when(w.observed_at)} · ${age(w.age_seconds)}`:'No durable heartbeat'}${w.stale?' · stale':''}${w.error_type?` · ${esc(w.error_type)}`:''}</div></div>`}).join('');const runtimeLabel=rt.operational?(rt.degraded?'Operational · degraded':'Operational'):'Attention';$('runtimeStatus').textContent=runtimeLabel;$('runtimeStatus').className=`status-val ${rt.operational?(rt.degraded?'warntext':'goodtext'):'badtext'}`;const val=String(rt.valuation_status||'unavailable'),valLabel=val==='cash_only'?'Cash-only · exact':val.replaceAll('_',' ');$('valuationStatus').textContent=valLabel;$('valuationStatus').className=`status-val ${val==='cash_only'||(val==='fresh'&&rt.valuation_fresh)?'goodtext':val==='partial'?'warntext':'badtext'}`;const failures=rt.allocation_family_failures||[];$('familyStatus').textContent=failures.length?`${failures.length} degraded`:'Healthy';$('familyStatus').className=`status-val ${failures.length?'warntext':'goodtext'}`;$('valuationDetail').textContent=`Cycle ${(rt.cycle_status||'unknown').replaceAll('_',' ')}${rt.fallback_snapshot?' · fallback accounting snapshot':''}${rt.settlement_evidence_blocked_count?` · ${rt.settlement_evidence_blocked_count} awaiting settlement evidence`:''}${rt.stale_position_count?` · ${rt.stale_position_count} stale position mark(s)`:''}`}
function researchTimeline(c){const x=[];if(c.source_observed_at)x.push(`${c.provider_status==='stale'?'Last':'Current'} source ${when(c.source_observed_at)} (${age(c.source_age_seconds)})`);else x.push('No current source timestamp');if(c.research_last_at)x.push(`Research evidence ${when(c.research_last_at)}`);if(c.research_due_at)x.push(c.research_due_state==='overdue'?`Research overdue since ${when(c.research_due_at)}`:`Next research expected ${when(c.research_due_at)}`);return x.join(' · ')}
function strategyDetails(rows){if(!rows?.length)return '';return `<details class="details"><summary>Strategy-level qualification evidence (${rows.length})</summary>${rows.map(s=>`<div class="strategy"><strong>${esc(s.name||s.strategy_id)}</strong> · ${esc(String(s.state||'unknown').replaceAll('_',' '))}<div class="d">Forward ${num(s.forward_outcomes)} / ${num(s.forward_required)} · mean ${pct(s.mean_forward_net_return)} · CI ${pct(s.mean_forward_net_return_ci_lower)} vs ${pct(s.required_mean_return_ci_lower)} required · hit CI ${pct(s.forward_hit_rate_ci_lower)} vs ${pct(s.required_hit_rate_ci_lower)} required · regimes ${num(s.observed_regime_count)} / ${num(s.required_regimes)}</div>${s.failed_gates?.length?`<div class="badtext d">Failed: ${esc(s.failed_gates.join(' · '))}</div>`:`<div class="goodtext d">No strategy-specific diagnostic gate currently failing</div>`}</div>`).join('')}</details>`}
function candidates(c){return (+c.raw_candidate_count||0)>0||(+c.emitted_candidate_count||0)>0||c.dominant_rejection_gate?`${num(c.raw_candidate_count)} / ${num(c.emitted_candidate_count)}`:'—'}function special(c){const rows=[];if(c.dominant_rejection_gate||Number.isFinite(+c.best_net_economics))rows.push(`Rejection gate: ${c.dominant_rejection_gate||'—'} · best net ${pct(c.best_net_economics)} · hurdle ${pct(c.required_net_economics)} · gap ${pct(c.gap_to_hurdle)}`);if(c.maker_shadow?.trials||c.maker_shadow?.outcomes)rows.push(`Maker shadow: ${num(c.maker_shadow.trials)} trials · ${num(c.maker_shadow.outcomes)} matured · ${num(c.maker_shadow.queue_confirmed_fills)} queue-confirmed fills · ${num(c.maker_shadow.adverse_selection_observations)} adverse-selection observations`);if(Number.isFinite(+c.capital_location?.mean_incremental_option_value))rows.push(`Location forward: mean incremental option value ${pct(c.capital_location.mean_incremental_option_value)} · positive rate ${pct(c.capital_location.positive_incremental_rate)}`);return rows.length?`<div class="details d">${rows.map(esc).join('<br>')}</div>`:''}
function renderCard(c){const src=c.provider_status==='connected'?`${num(c.source_item_count)} admitted items · ${num(c.independent_source_count)} independent source groups`:c.provider_status==='stale'?`${(c.stale_source_ids||[]).length} stale configured sources`:'no admitted current source';const classes=(c.missing_evidence_classes||[]).length?`Missing: ${c.missing_evidence_classes.join(', ')}`:`Covered: ${(c.covered_evidence_classes||[]).join(', ')||'n/a'}`;return `<article class="card"><div class="cardhead"><div><div class="name">${esc(c.name)}</div><div class="meta">Provider ${esc(c.provider_status)} · evidence ${esc(String(c.evidence_status||'').replaceAll('_',' '))} · research ${esc(c.research_status)} · last conclusion ${esc(c.last_conclusion)}</div></div><span class="badge ${clsStatus(c.status)}">${esc(c.status)}</span></div><div class="cardmetrics">${metric('Current source',num(c.source_item_count),`${src} · ${classes}`,clsStatus(c.provider_status))}${metric('Raw / emitted',candidates(c),c.dominant_rejection_gate?`dominant gate: ${String(c.dominant_rejection_gate).replaceAll('_',' ')}`:'candidate funnel not published')}${metric('Signals',num(c.signal_count),'research signals')}${metric('Forward',`${num(c.forward_outcome_count)} / ${num(c.forward_target)}`,'independent outcomes',c.forward_outcome_count>=c.forward_target?'good':'')}${metric('Qualified',num(c.qualified_count),'current statistical gate',c.qualified_count>0?'good':'')}${metric('Paper-capable',c.paper_capable?'Yes':'No',c.paper_capable?'current source + decision grade':'fail-closed',c.paper_capable?'good':'')}${metric('Settled',`${num(c.settled_count)} / ${num(c.settled_target)}`,'allocator outcomes',c.settled_count>=c.settled_target?'good':'')}${metric('Certified',c.certified?'Yes':'No','profitability certification',c.certified?'good':'')}</div><div class="strip">${metric('Forward mean',pct(c.mean_forward_net_return),'net return')}${metric('CI lower',pct(c.mean_forward_net_return_ci_lower),'forward mean lower bound')}${metric('Hit rate',pct(c.forward_hit_rate),'forward outcomes')}${metric('Realized P&L',money(c.allocator_realized_profit_usd),'paper allocator')}</div>${special(c)}<div class="reason"><strong>Current blocker:</strong> ${esc(c.primary_blocker)}</div><div class="next"><strong>Next:</strong> ${esc(c.next_action)}</div><div class="time">${esc(researchTimeline(c))}</div>${strategyDetails(c.strategy_evidence)}</article>`}
function renderSummary(s){$('summary').innerHTML=[stat('Provider connected',`${num(s.provider_connected)} / ${num(s.lane_count)}`,'current canonical source truth'),stat('Evidence complete',`${num(s.evidence_complete)} / ${num(s.lane_count)}`,'required classes satisfied'),stat('Current source data',`${num(s.current_source_data)} / ${num(s.lane_count)}`,'lanes with admitted current items'),stat('Raw / emitted',`${num(s.raw_candidates)} / ${num(s.emitted_candidates)}`,'candidate funnel'),stat('Forward mature',`${num(s.forward_mature)} / ${num(s.lane_count)}`,'met genuine forward target'),stat('Qualified / paper / certified',`${num(s.qualified_lanes)} / ${num(s.paper_capable_lanes)} / ${num(s.certified_lanes)}`,'governed current conclusions')].join('')}
function renderQueue(p){const legacy=p.command_center?.queue?.actions||[],cards=(p.cards||[]).filter(c=>!c.certified||c.primary_blocker).map(c=>({name:c.name,state:c.status,reason:c.primary_blocker,next:c.next_action})),seen=new Set(),rows=[...cards,...legacy.map(x=>({name:x.name||x.asset||'Portfolio action',state:x.state||'attention',reason:x.primary_reason||x.reason||'No reason recorded',next:x.next_action||'Continue governed monitoring'}))].filter(x=>{const k=`${x.name}|${x.reason}`;if(seen.has(k))return false;seen.add(k);return true}).slice(0,16);$('actionQueue').innerHTML=rows.length?rows.map(x=>`<div class="queue-item"><div class="queue-title"><strong>${esc(x.name)}</strong><span class="badge ${clsStatus(x.state)}">${esc(String(x.state||'attention').replaceAll('_',' '))}</span></div><div class="item-sub">${esc(x.reason)}</div><div class="next">Next: ${esc(x.next)}</div></div>`).join(''):empty('No unresolved portfolio or mechanism actions.')}
function renderUniverse(u){if(!u?.available){$('volumeUniverse').textContent='Current volume-universe snapshot unavailable.';return}const assets=(u.assets||[]).slice(0,25).map(x=>x.asset).filter(Boolean);$('volumeUniverse').innerHTML=`<strong>${num(u.asset_count||assets.length)} assets</strong> · ${esc(u.method||u.ranking_metric||'volume-ranked')} · ${u.observed_at?`observed ${esc(when(u.observed_at))}`:'timestamp unavailable'}${u.stale?' · <span class="warntext">stale</span>':''}<br>${esc(assets.join(' · '))}`}
function render(p){const cc=p.command_center||{},perf=cc.performance||{},portfolio=cc.portfolio||{},history=cc.history||{},s=p.summary||{};$('contract').textContent=`V5 cards · ${(p.release_commit||'unknown').slice(0,7)}`;$('nav').textContent=money(perf.current_nav_usd);$('totalReturn').textContent=`${+perf.total_return>=0?'+':''}${pct(perf.total_return)} since $250,000 genesis`;$('totalReturn').className=`return ${pnlClass(perf.total_return)}`;$('updated').textContent=portfolio.observed_at?`Last portfolio snapshot ${when(portfolio.observed_at)}`:'Portfolio awaiting first worker snapshot';$('cash').textContent=money(perf.cash_usd);$('deployed').textContent=money(perf.reserved_capital_usd);$('realized').textContent=money(perf.realized_pnl_usd);$('realized').className=`v ${pnlClass(perf.realized_pnl_usd)}`;$('unrealized').textContent=money(perf.unrealized_pnl_usd);$('unrealized').className=`v ${pnlClass(perf.unrealized_pnl_usd)}`;$('maxdd').textContent=pct(perf.max_drawdown_fraction);$('openCount').textContent=num(perf.open_position_count);$('tradeCount').textContent=num(perf.closed_trade_count);$('certifiedCount').textContent=`${num(s.certified_lanes)} / ${num(s.lane_count)}`;$('historyCount').textContent=`${num(history.count||0)} NAV snapshots`;renderRuntime(p);renderChart(history.snapshots);renderAttribution(cc.attribution||{});renderPositions(cc.positions?.positions||[]);renderTrades(cc.trades?.trades||[]);renderSkips(cc.skips?.skips||[]);renderCycleHistory(cc.cycle_history||{});renderSummary(s);$('cards').innerHTML=(p.cards||[]).length?p.cards.map(renderCard).join(''):empty('No mechanism cards are available.');renderQueue(p);renderUniverse(p.system?.volume_universe||{})}
async function refresh(){const b=$('refreshBtn');b.disabled=true;$('error').classList.remove('show');try{const r=await fetch('/v3/dashboard/v5-snapshot',{cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);const p=await r.json();if(p.dashboard_ui_contract_version!=='v5_mechanism_truth')throw new Error(`Unexpected card contract ${p.dashboard_ui_contract_version||'missing'}`);render(p)}catch(e){$('error').textContent=`Dashboard refresh failed: ${e.message}`;$('error').classList.add('show')}finally{b.disabled=false}}
$('refreshBtn').addEventListener('click',refresh);window.addEventListener('resize',()=>renderChart(window.__history||[]));refresh();setInterval(refresh,30000);
</script></body></html>'''
